import re,sys
from collections import defaultdict
pat=re.compile(r'^\s*<'+sys.argv[2]+r'\s')
succ=defaultdict(set); attrs=set(); seqs=[]
for fn in sys.argv[3:]:
    for line in open(fn):
        if not pat.match(line): continue
        names=re.findall(r'\s([a-zA-Z_][a-zA-Z0-9_-]*)=',line)
        seqs.append(names); attrs.update(names)
        for i in range(len(names)):
            for j in range(i+1,len(names)): succ[names[i]].add(names[j])
# Kahn: repeatedly pick attr with no remaining predecessor; tie-break: most successors then name
pred=defaultdict(set)
for a in attrs:
    for b in succ[a]: pred[b].add(a)
rem=set(attrs); out=[]
while rem:
    cands=[a for a in rem if not (pred[a]&rem)]
    if not cands:
        out.append('!!CYCLE!!'+str(sorted(rem))); break
    cands.sort(key=lambda a:(-len(succ[a]&rem),a))
    pick=cands[0]; out.append(pick); rem.discard(pick)
print("ORDER:"," ".join(out))
idx={a:i for i,a in enumerate(out)}
viol=0
for s in seqs:
    ii=[idx.get(a,-1) for a in s]
    if ii!=sorted(ii): viol+=1; print("VIOLATION:",s)
print("lines=%d violations=%d"%(len(seqs),viol))
